KEV/1.0 domain=BLENDER_BPY target=Modulo_01
@SPACE{X=4.0;Y=0.4;Z=3.0}
@GRAPH[
  S1:MOD.bmesh_new() -> S2
  S2:MOD.create_cube(size=1.0) -> S3
  S3:MOD.scale_verts(X=-2.0,Y=-0.2,Z=0.0) -> S4
  S4:MOD.convex_hull() -> S5
]
@GUARD[
  !RULE-01: PROIBIDO bpy.ops.uv.smart_project sem VIEW_3D em --background (gera RuntimeError poll failed).
  !RULE-02: PROIBIDO bmesh.ops.create_cube(bm, size=SX) seguido de v.co *= SX (gera erro 300% escala quadratica SX^2!).
]
@VERIFY[
  ?bm==bmesh.new_type
  ?cube_size==1.0
  ?final_scale_X==-2.0
  ?convex_hull_valid==True
]

KEV/1.0 domain=UE5_CPP target=InteractionInventorySystem
@SPACE{k1=UHT_ORDER;k2=GC_SAFE;k3=NO_TICK;k4=BLUEPRINT_API}
@GRAPH[
  S1:UHT_ORDER.check() -> S2
]
@GUARD[
  !RULE-01: #include "InteractionInventorySystem.generated.h" deve ser o último include para injetar Super/ThisClass corretamente.
  !RULE-02: Membros ponteiros UObject sem UPROPERTY() são coletados pelo GC; usar TObjectPtr e VisibleAnywhere.
  !RULE-03: Componentes de ator devem desabilitar bCanEverTick se operarem via FTimerManager ou eventos, não via Tick.
]
@VERIFY[
  ?UHT_ORDER==LAST_INCLUDE
  ?GC_SAFE==TObjectPtr_USAGE
  ?NO_TICK==bCanEverTick_FALSE
  ?BLUEPRINT_API==DELEGATE_DEFINED
]

KEV/1.0 domain=BRIDGE_3D target=ModularBridgeAssetActor
@SPACE{k1=Var_01_Standard;k2=Socket_Muzzle;k3=Socket_Grip}
@GRAPH[
  S1:MOD.bmesh.scale_length(v1=1.0) -> S2
  S2:MOD.bmesh.create_variants(p1=Var_01_Standard,p2=Var_02_Compact,p3=Var_03_Heavy) -> S3
  S3:MOD.bmesh.add_sockets(p1=Socket_Muzzle,p2=Socket_Grip) -> S4
  S4:MOD.bmesh.export_meshes(p1=glb,p2=fbx,format=UCX_Var_01_Standard_01) -> S5
]
@GUARD[
  !RULE-01: Blender escala METRIC (Z-up) deve ser 1.0m, nunca centímetros; Var_03_Heavy tem dimensões 1.25m x 0.18m x 0.32m.
  !RULE-02: Sockets Socket_Muzzle e Socket_Grip devem usar SnapToTargetNotIncludingScale para evitar herança de escala não uniforme do FBX/glTF.
]
@VERIFY[
  ?FModularBridgeVariantRow==public_FTableRowBase
  ?ExpectedDimensionsMeters==1.00
  ?Socket_MuzzleName=="Socket_Muzzle"
  ?SnapToTargetNotIncludingScale==true
]

