KEV/1.0 domain=BLENDER_BPY target=Modulo_01
@SPACE{unit=METRIC;scale=1.0;up=Z;size_x=4.0;size_y=0.4;size_z=3.0;pivot_z_min=0.0;collider=UCX_Modulo_01}
@GRAPH[
  S1:BMESH.init_metric(scale=1.0,empty=true) -> S2
  S2:BMESH.create_cube_and_inset(sx=4.0,sy=0.4,sz=3.0,z_min=0.0,inset_depth=-0.08,mesh_name=Modulo_01) -> S3
  S3:BMESH.loops_uv_verify_grid(outward=true,overlap=0.0,mesh_name=Modulo_01) -> S4
  S4:BMESH.convex_hull_collider(name=UCX_Modulo_01,sx=4.0,sy=0.4,sz=3.0,z_min=0.0,manifold=true) -> S5
  S5:IO.export_assets(glb="Modulo_01.glb",fbx="Modulo_01.fbx",dir=os.environ.getKEV_EXPORT_DIR)
]
@GUARD[
  !NO-VIEW3D-OPS: Construir geometria e UVs exclusivamente via bmesh e bm.loops.layers.uv.verify sem depender de janela 3D ativa
  !MANIFOLD-UCX: Garantir non_manifold_edges==0 e recalc_face_normals no colisor UCX_Modulo_01 da Unreal Engine 5
  !PIVOT-ORIGIN-Z0: Manter origin em (0,0,0) e base apoiada em Z_min=0.0 dentro de +-2% da AABB oficial
]
@VERIFY[
  ?non_manifold_edges==0
  ?zero_area_faces==0
  ?unit_scale==1.0
  ?bbox_tol_pct<=2.0
]

KEV/1.0 domain=UE5_CPP target=InteractionInventorySystem
@SPACE{unit=CM;scale=100.0;up=Z;max_dist_cm=250.0;cooldown_s=1.5;tick_rate_hz=60.0;mesh=TObjectPtr_UStaticMeshComponent;display_mesh=TObjectPtr_UStaticMeshComponent;interaction_sphere=TObjectPtr_USphereComponent}
@GRAPH[
  S1:UHT.header_order(pragma_once=true,last_include="InteractionInventorySystem.generated.h") -> S2
  S2:UHT.delegates_and_struct(multicast=true,blueprint_assignable=true,tick_rate=60.0) -> S3
  S3:UCLASS.component(name=UInteractionInventoryComponent,base=UActorComponent,tick=false,mesh=TObjectPtr_UStaticMeshComponent,timer=FTimerHandle,sphere=TObjectPtr_USphereComponent) -> S4
  S4:AINTERACTOR.actor(name=AInteractableWorldActor,base=AActor,tick=false,mesh=TObjectPtr_UStaticMeshComponent,timer=FTimerHandle,sphere=TObjectPtr_USphereComponent)
]
@GUARD[
  !UHT-LAST-INCLUDE: Incluir InteractionInventorySystem.generated.h estritamente por ultimo no header sem violar UHT order
  !GC-SAFE-TOBJECTPTR: Declarar todo membro UObject/AActor/UActorComponent com UPROPERTY(...) e TObjectPtr<T> no construtor
  !NO-RAW-NEW-UOBJECT: Instanciar componentes via CreateDefaultSubobject<T> no construtor sem new bruto
  !TIMER-NO-TICK: Desativar bCanEverTick em PrimaryComponentTick e PrimaryActorTick, limpar timer no EndPlay
]
@VERIFY[
  ?generated_h_last==1
  ?raw_uobject_ptrs==0
  ?raw_new_uobject==0
  ?clang_cpp20_errors==0
]

KEV/1.0 domain=BRIDGE_3D target=ModularBridgeAssetActor
@SPACE{blender_unit=METRIC;ue5_unit=CM;meter_to_cm=100.0;up=Z;variations=3;sx=1.0;sy=0.16;sz=0.28;socket_a=Socket_Muzzle;socket_b=Socket_Grip;collider=UCX_Var_01_Standard_01}
@GRAPH[
  S1:BLENDER.build_3_variations_bmesh(v1_x=1.0,v2_x=0.8,v3_x=1.25,sy=0.16,sz=0.28,z_min=0.0,mesh_type=2) -> S2
  S2:BLENDER.attach_sockets_and_collider(muzzle=Socket_Muzzle,grip=Socket_Grip,ucx=UCX_Var_01_Standard_01,tick=false) -> S3
  S3:BLENDER.export_glb_fbx(glb="ModularBridgePack.glb",fbx="ModularBridgePack.fbx") -> S4
  S4:UE5.ustruct_datatable_row(name=FModularBridgeVariantRow,meter_to_cm=100.0,tick=false) -> S5
  S5:UE5.actor_socket_validator(actor=AModularBridgeAssetActor,rule=SnapToTargetNotIncludingScale,tol_pct=2.0)
]
@GUARD[
  !SCALE-1M-100CM: Multiplicar dimensoes em metros do Blender por 100.0 para validar FBox em centimetros no UE5 (±2%)
  !SOCKET-EXACT-NAMES: Preservar literalmente Socket_Muzzle e Socket_Grip no Blender e no DoesSocketExist do C++
]
@VERIFY[
  ?variations==3
  ?non_manifold_edges==0
  ?meter_to_cm==100.0
  ?clang_cpp20_errors==0
]
